clearClipboard() {
  if command -v pbcopy >/dev/null 2>&1; then
    printf '' | pbcopy
  elif command -v wl-copy >/dev/null 2>&1; then
    printf '' | wl-copy
  elif command -v xclip >/dev/null 2>&1; then
    printf '' | xclip -selection clipboard
  fi
}

cleanupRollout() {
  MENU_SYNC_TRIGGER_SECRET=""
  unset MENU_SYNC_TRIGGER_SECRET
  clearClipboard || true
  if [[ "$SUPABASE_WORKDIR" == /tmp/cupedia-764-supabase.* && -d "$SUPABASE_WORKDIR" ]]; then
    rm -rf -- "$SUPABASE_WORKDIR"
  fi
  if [[ "$VERCEL_WORKDIR" == /tmp/cupedia-764-vercel.* && -d "$VERCEL_WORKDIR" ]]; then
    rm -rf -- "$VERCEL_WORKDIR"
  fi
}
