assertOutsidePrimaryWindow() {
  local in_primary_window
  in_primary_window=$(node <<'NODE'
const now = new Date();
const hour = now.getUTCHours();
const minute = now.getUTCMinutes();
const primaryHour = hour === 0 || hour === 3 || hour === 9;
process.stdout.write(primaryHour && minute >= 17 && minute <= 32 ? 'yes' : 'no');
NODE
)
  if [[ "$in_primary_window" == "yes" ]]; then
    warn "current time is inside a Supabase primary minute-17-to-32 window"
    exit 1
  fi
}

supabaseQuery() {
  supabase db query \
    --workdir "$SUPABASE_WORKDIR" \
    --linked \
    --output json \
    "$1"
}

readSchedulerState() {
  # pg_net exposes this as a void function: success means the call completes,
  # while an unhealthy worker raises an exception. Run it separately so we do
  # not mistake PostgreSQL's non-NULL void sentinel for a failed check.
  supabaseQuery "SELECT net.check_worker_is_up();" >/dev/null
  supabaseQuery "
    SELECT activation.environment,
           activation.active AS scheduler_active,
           activation.activated_at,
           job.active AS job_active,
           job.jobid,
           job.schedule,
           job.command,
           job.database,
           current_database() AS current_database,
           job.username,
           current_setting('cron.timezone') AS cron_timezone,
           current_setting('pg_net.ttl', true) AS pg_net_ttl,
           extract(epoch FROM current_setting('pg_net.ttl', true)::interval)::integer
             AS pg_net_ttl_seconds,
           true AS worker_check_completed,
           (SELECT count(*)::integer FROM net.http_request_queue) AS pending_requests,
           (SELECT count(*)::integer FROM vault.secrets WHERE name = '${VAULT_SECRET_NAME}') AS vault_secret_count
    FROM canteen_menu_scheduler.activation AS activation
    JOIN cron.job AS job
      ON job.jobname = 'cupedia-canteen-menu-sync-wakeup'
    WHERE activation.singleton;
  "
}

readVaultMetadata() {
  supabaseQuery "
    SELECT id::text, name, created_at, updated_at
    FROM vault.secrets
    WHERE name = '${VAULT_SECRET_NAME}'
    ORDER BY created_at;
  "
}

readTransportBoundary() {
  supabaseQuery "
    SELECT
      (SELECT count(*)::integer
       FROM pg_extension
       WHERE extname IN ('pg_cron', 'pg_net', 'supabase_vault'))
        AS extension_count,
      (SELECT count(*)::integer
       FROM pg_roles
       WHERE rolname IN ('anon', 'authenticated')) AS client_role_count,
      (SELECT bool_and(NOT rolcanlogin)
       FROM pg_roles
       WHERE rolname IN ('anon', 'authenticated')) AS client_roles_no_login,
      (SELECT count(*)::integer
       FROM pg_class AS class
       JOIN pg_namespace AS namespace ON namespace.oid = class.relnamespace
       WHERE namespace.nspname = 'net'
         AND class.relname IN ('http_request_queue', '_http_response'))
        AS transport_table_count,
      (SELECT bool_and(class.relpersistence = 'u')
       FROM pg_class AS class
       JOIN pg_namespace AS namespace ON namespace.oid = class.relnamespace
       WHERE namespace.nspname = 'net'
         AND class.relname IN ('http_request_queue', '_http_response'))
        AS transport_tables_unlogged,
      (SELECT array_agg(column_name::text ORDER BY ordinal_position) = ARRAY[
         'id',
         'expected_tick_at',
         'sync_window_key',
         'cron_run_id',
         'request_id',
         'request_created_at',
         'http_status',
         'delivery_error',
         'endpoint_disposition',
         'business_code',
         'completed_at'
       ]::text[]
       FROM information_schema.columns
       WHERE table_schema = 'canteen_menu_scheduler'
         AND table_name = 'delivery_audit') AS scheduler_audit_columns_exact;
  "
}

assertTransportBoundary() {
  local transport_boundary
  transport_boundary=$(readTransportBoundary)
  if ! jq -e '
    .rows | length == 1 and
    .[0].extension_count == 3 and
    .[0].client_role_count == 2 and
    .[0].client_roles_no_login and
    .[0].transport_table_count == 2 and
    .[0].transport_tables_unlogged and
    .[0].scheduler_audit_columns_exact
  ' >/dev/null <<<"$transport_boundary"; then
    warn "Supabase extensions or the private pg_net transport boundary differ from the reviewed state"
    jq '.rows' <<<"$transport_boundary"
    exit 1
  fi
}

assertNoReviewRequiredSources() {
  local explicit_review recent_retry_limits
  explicit_review=$(supabaseQuery "
    SELECT id, provider, external_store_id, last_error_code
    FROM public.canteen_menu_sources
    WHERE enabled
      AND last_error_code IS NOT NULL
      AND (
        last_error_code LIKE 'INVALID_%'
        OR last_error_code IN (
          'MENU_SYNC_CONFLICT',
          'MENU_SYNC_IDENTITY_CHURN',
          'MENU_SYNC_SUSPICIOUS_DROP'
        )
      )
    ORDER BY provider, external_store_id;
  ")
  if ! jq -e '.rows | length == 0' >/dev/null <<<"$explicit_review"; then
    warn "an enabled source has an explicit review-required error"
    jq '.rows' <<<"$explicit_review"
    exit 1
  fi

  recent_retry_limits=$(supabaseQuery "
    WITH classified_runs AS (
      SELECT
        source.id AS source_id,
        source.provider,
        source.external_store_id,
        run.status,
        run.error_code,
        run.started_at,
        (run.started_at AT TIME ZONE 'Asia/Hong_Kong')::date AS hkt_date,
        CASE
          WHEN extract(hour FROM run.started_at AT TIME ZONE 'Asia/Hong_Kong') < 11
            THEN 'breakfast'
          WHEN extract(hour FROM run.started_at AT TIME ZONE 'Asia/Hong_Kong') < 17
            THEN 'lunch'
          ELSE 'dinner'
        END AS meal_period
      FROM public.canteen_menu_sync_runs AS run
      JOIN public.canteen_menu_sources AS source
        ON source.id = run.menu_source_id
      WHERE source.enabled
        AND run.started_at >= now() - interval '24 hours'
    ),
    latest_success AS (
      SELECT
        source_id,
        hkt_date,
        meal_period,
        max(started_at) AS started_at
      FROM classified_runs
      WHERE status IN ('applied', 'unchanged')
      GROUP BY source_id, hkt_date, meal_period
    )
    SELECT
      run.provider,
      run.external_store_id,
      run.hkt_date,
      run.meal_period,
      count(*)::integer AS failures_after_latest_success,
      array_agg(run.error_code ORDER BY run.started_at) AS error_codes
    FROM classified_runs AS run
    LEFT JOIN latest_success AS success
      ON success.source_id = run.source_id
     AND success.hkt_date = run.hkt_date
     AND success.meal_period = run.meal_period
    WHERE run.status = 'failed'
      AND coalesce(run.error_code, '') <> 'MENU_SYNC_SUPERSEDED'
      AND (success.started_at IS NULL OR run.started_at > success.started_at)
    GROUP BY
      run.source_id,
      run.provider,
      run.external_store_id,
      run.hkt_date,
      run.meal_period
    HAVING count(*) >= 3
    ORDER BY
      run.hkt_date DESC,
      run.meal_period,
      run.provider,
      run.external_store_id;
  ")
  if ! jq -e '.rows | length == 0' >/dev/null <<<"$recent_retry_limits"; then
    warn "a source reached the retry limit after its latest success in a recent meal window"
    jq '.rows' <<<"$recent_retry_limits"
    exit 1
  fi
}

