}

assertMainAndProductionDeployment() {
  local compare_status deployment deployment_sha deployment_state

  main_sha=$(gh api "repos/${REPOSITORY}/commits/main" --jq .sha)
  compare_status=$(gh api \
    "repos/${REPOSITORY}/compare/${ROLLOUT_COMMIT}...${main_sha}" \
    --jq .status)
  if [[ "$compare_status" != "identical" && "$compare_status" != "ahead" ]]; then
    warn "main does not contain rollout commit ${ROLLOUT_COMMIT}"
    exit 1
  fi

  workflow_text=$(gh api \
    -H 'Accept: application/vnd.github.raw+json' \
    "repos/${REPOSITORY}/contents/.github/workflows/canteen-menu-sync.yml?ref=main")
  if ! printf '%s' "$workflow_text" | \
    node "$ROLLOUT_CONTRACT_SCRIPT" validate-workflow; then
    warn "main does not contain the reviewed delayed fallback schedules"
    exit 1
  fi

  deployment=$(vercel list "$VERCEL_PROJECT" \
    --scope "$VERCEL_SCOPE" \
    --environment production \
    --format json 2>/dev/null | jq -c \
      'if type == "array" then .[0] else .deployments[0] end')
  deployment_sha=$(jq -r '.meta.githubCommitSha // empty' <<<"$deployment")
  deployment_state=$(jq -r '.state // .readyState // empty' <<<"$deployment")
  if [[ "$deployment_state" != "READY" || "$deployment_sha" != "$main_sha" ]]; then
    warn "Vercel Production is not Ready on the current main commit"
    jq '{url, state, readyState, commit: .meta.githubCommitSha}' <<<"$deployment"
    exit 1
  fi
}

