  local issue757_state issue763_state
  issue757_state=$(gh issue view 757 --repo "$REPOSITORY" --json state --jq .state)
  issue763_state=$(gh issue view 763 --repo "$REPOSITORY" --json state --jq .state)
  if [[ "$issue757_state" != "OPEN" ]]; then
    warn "issue #757 must remain open during rollout and observation"
    exit 1
  fi
  production_recovery_clean=false
  if [[ "$issue763_state" == "CLOSED" ]]; then
