verifyFirstNaturalWindow() {
  local active_state activated_at bounds window_start health_to fallback_from
  local fallback_to verify_after window_hkt now_epoch verify_epoch
  local delivery_health window_health fallback_runs fallback_run fallback_run_id
  local fallback_run_url fallback_sha fallback_compare fallback_logs vercel_logs
  local evidence_comment

  assertMainAndProductionDeployment
  readIssueGateState
  assertTransportBoundary
  active_state=$(readSchedulerState)
  if ! jq -e '
    .rows | length == 1 and
    .[0].environment == "production" and
    .[0].scheduler_active and
    .[0].job_active and
    .[0].vault_secret_count == 1
  ' >/dev/null <<<"$active_state"; then
    warn "the reviewed production scheduler is not active"
    jq '.rows' <<<"$active_state"
    exit 1
  fi

  activated_at=$(jq -r '.rows[0].activated_at // empty' <<<"$active_state")
  bounds=$(node "$ROLLOUT_CONTRACT_SCRIPT" first-primary-window "$activated_at")
  IFS=$'\t' read -r window_start health_to fallback_from fallback_to verify_after window_hkt <<<"$bounds"
  now_epoch=$(date +%s)
  verify_epoch=$(node -e 'process.stdout.write(String(Date.parse(process.argv[1]) / 1000))' "$verify_after")
  if (( now_epoch < verify_epoch )); then
    warn "the first natural primary window has not finished its fallback observation period"
    note "first primary starts ${window_hkt} HKT; rerun with: scripts/issue-764-production-rollout-wizard.sh verify"
    exit 1
  fi

  delivery_health=$(supabaseQuery "
    SELECT classification, count(*)::integer AS count
    FROM canteen_menu_scheduler.delivery_health(
      '${window_start}'::timestamptz,
      '${health_to}'::timestamptz
    )
    GROUP BY classification
    ORDER BY classification;
  ")
  if ! jq -e '
    ([.rows[].count] | add) == 16 and
    all(.rows[]; .classification == "primary-progress" or .classification == "primary-no-work")
  ' >/dev/null <<<"$delivery_health"; then
    warn "the first primary window contains missing or failed delivery evidence"
    jq '.rows' <<<"$delivery_health"
    exit 1
  fi

  window_health=$(supabaseQuery "
    SELECT *
    FROM canteen_menu_scheduler.window_health(
      '${window_start}'::timestamptz,
      '${health_to}'::timestamptz
    );
  ")
  if ! jq -e '
    .rows | length == 1 and
    .[0].classification == "primary-drained-window" and
    .[0].primary_completed_at != null and
    .[0].required_source_count == .[0].primary_completed_source_count and
    .[0].enqueue_failure_count == 0 and
    .[0].http_failure_count == 0 and
    .[0].endpoint_rejection_count == 0 and
    .[0].provider_failure_count == 0 and
    .[0].retry_later_count == 0 and
    .[0].review_required_count == 0 and
    .[0].inapplicable_run_count == 0
  ' >/dev/null <<<"$window_health"; then
    warn "the first window did not complete through the healthy Supabase primary"
    jq '.rows' <<<"$window_health"
    exit 1
  fi

  fallback_runs=$(gh run list \
    --repo "$REPOSITORY" \
    --workflow canteen-menu-sync.yml \
    --event schedule \
    --limit 50 \
    --json databaseId,createdAt,conclusion,status,url,headSha)
  fallback_run=$(jq -c \
    --arg from "$fallback_from" \
    --arg to "$fallback_to" '
      [.[] | select(
        (.createdAt | fromdateiso8601) >= ($from | fromdateiso8601) and
        (.createdAt | fromdateiso8601) <= ($to | fromdateiso8601)
      )] | sort_by(.createdAt) | .[0] // empty
    ' <<<"$fallback_runs")
  if [[ -z "$fallback_run" ]] || ! jq -e \
    '.status == "completed" and .conclusion == "success"' \
    >/dev/null <<<"$fallback_run"; then
    warn "the delayed GitHub fallback is not yet independently successful"
    [[ -n "$fallback_run" ]] && jq . <<<"$fallback_run"
    exit 1
  fi

  fallback_run_id=$(jq -r .databaseId <<<"$fallback_run")
  fallback_run_url=$(jq -r .url <<<"$fallback_run")
  fallback_sha=$(jq -r .headSha <<<"$fallback_run")
  fallback_compare=$(gh api \
    "repos/${REPOSITORY}/compare/${ROLLOUT_COMMIT}...${fallback_sha}" \
    --jq .status)
  if [[ "$fallback_compare" != "identical" && "$fallback_compare" != "ahead" ]]; then
    warn "the delayed GitHub fallback did not run from a commit containing the rollout baseline"
    exit 1
  fi
  fallback_logs=$(gh run view "$fallback_run_id" --repo "$REPOSITORY" --log)
  if [[ "$fallback_logs" != *'Call 1/16: no-work'* ]]; then
    warn "the delayed GitHub fallback did not record an immediate no-work drain"
    exit 1
  fi
  if grep -Eiq 'authorization:|bearer[[:space:]]|decrypted_secret|MENU_SYNC_TRIGGER_SECRET=' \
    <<<"$fallback_logs"; then
    warn "the delayed GitHub fallback log contains a sensitive-data marker"
    exit 1
  fi

  vercel_logs=$(vercel logs \
    --project "$VERCEL_PROJECT" \
    --scope "$VERCEL_SCOPE" \
    --environment production \
    --since "$window_start" \
    --until "$fallback_to" \
    --query "/api/internal/canteen-menu-sync/next" \
    --limit 500 \
    --json 2>/dev/null)
  if grep -Eiq 'authorization:|bearer[[:space:]]|decrypted_secret|MENU_SYNC_TRIGGER_SECRET=|provider[_ -]?payload|raw[_ -]?response' \
    <<<"$vercel_logs"; then
    warn "the bounded Vercel production logs contain a sensitive-data marker"
    exit 1
  fi

  active_state=$(readSchedulerState)
  if ! jq -e '.rows | length == 1 and .[0].pending_requests == 0' \
    >/dev/null <<<"$active_state"; then
    warn "pg_net still has a pending request after the observation window"
    jq '.rows' <<<"$active_state"
    exit 1
  fi

  evidence_comment=$(jq -rn \
    --arg window_hkt "$window_hkt" \
    --arg deployment "$main_sha" \
    --arg fallback_url "$fallback_run_url" \
    --arg recovery_clean "$production_recovery_clean" \
    --argjson delivery "$(jq '.rows' <<<"$delivery_health")" \
    --argjson window "$(jq '.rows[0]' <<<"$window_health")" '
      "Production rollout evidence (HKT)\n\n" +
      "- Deployment: `" + $deployment + "` (Vercel Production Ready)\n" +
      "- Scheduler: `cupedia-canteen-menu-sync-wakeup`, `17-32 0,3,9 * * *`, active in production\n" +
      "- First natural primary start: " + $window_hkt + " HKT\n" +
      "- Delivery classifications: `" + ($delivery | tostring) + "`\n" +
      "- Window health: `" + ($window | tostring) + "`\n" +
      "- Pending pg_net requests after observation: 0\n" +
      "- Delayed GitHub fallback: " + $fallback_url + " (successful immediate no-work)\n\n" +
      "The runtime scheduler audit schema matched its bounded metadata allowlist, and bounded GitHub/Vercel logs contained no sensitive-data markers. No bearer, authorization header, raw response body, or provider payload was queried or copied into this evidence. #757 was confirmed open. " +
      (if $recovery_clean == "true" then
        "#763 is closed, so the separate seven-day acceptance gate may begin from the reviewed clean recovery point."
       else
        "#763 is still open, so the seven-day acceptance clock has not started."
       end)
  ')

  if confirm "Post this bounded evidence to issue #764?"; then
    printf '%s\n' "$evidence_comment" | gh issue comment 764 \
      --repo "$REPOSITORY" \
      --body-file - >/dev/null
    say "Issue #764 now records the first natural production window."
  else
    warn "verification passed locally, but issue #764 was not updated"
    exit 1
  fi
}

if [[ "$MODE" != "rollout" && "$MODE" != "verify" ]]; then
  printf 'Usage: %s [rollout|verify]\n' "$0" >&2
  exit 2
fi

cd "$REPO_ROOT"

if [[ "$MODE" == "verify" ]]; then
  TOTAL_STAGES=2
  banner "CUpedia · Issue #764 production verification"

  stage "Connect read-only evidence tools"
  say "We reconnect to production without reading or changing any bearer value."
  prepareConnections
  assertMainAndProductionDeployment
  readIssueGateState

  stage "Verify the first natural primary window"
  verifyFirstNaturalWindow
  finish
  exit 0
fi

banner "CUpedia · Issue #764 production rollout"

stage "Safety preflight"
say "We verify every fail-closed boundary before touching credentials."
prepareConnections
assertMainAndProductionDeployment
readIssueGateState

assertNoMenuSyncRun
assertRotationGap
assertOutsidePrimaryWindow

scheduler_state=$(readSchedulerState)
if ! jq -e '
  .rows as $rows |
  ($rows | length == 1) and
  $rows[0].environment == "unconfigured" and
  ($rows[0].scheduler_active | not) and
  ($rows[0].job_active | not) and
  $rows[0].schedule == "17-32 0,3,9 * * *" and
  $rows[0].command == "SELECT canteen_menu_scheduler.enqueue_canteen_menu_sync_wakeup()" and
  $rows[0].database == $rows[0].current_database and
  $rows[0].username == "postgres" and
  (["GMT", "UTC", "Etc/GMT", "Etc/UTC"] | index($rows[0].cron_timezone)) != null and
  $rows[0].pg_net_ttl_seconds > 0 and
  $rows[0].pg_net_ttl_seconds <= 21600 and
  $rows[0].worker_check_completed and
  $rows[0].pending_requests == 0 and
  ($rows[0].vault_secret_count == 0 or $rows[0].vault_secret_count == 1)
' >/dev/null <<<"$scheduler_state"; then
  warn "scheduler installation is not in the reviewed inactive state"
  jq '.rows' <<<"$scheduler_state"
  exit 1
fi

assertTransportBoundary

say "Database scheduler is exact, inactive, queue-empty, and worker-healthy."
assertNoReviewRequiredSources
open_url "$SUPABASE_DATA_API_URL"
step "Sign in to ${SUPABASE_PROJECT_NAME} if needed."
step "Confirm Exposed schemas is exactly public, graphql_public."
step "Stop if net appears anywhere in the exposed-schema list."
if ! confirm "Does the dashboard still show only public and graphql_public?"; then
  warn "Data API boundary was not confirmed; rollout stopped"
  exit 1
fi

stage "Create or rotate the Vault secret"
say "The new bearer stays only in process memory and your clipboard. It is never written to .env."
askEphemeralSecret MENU_SYNC_TRIGGER_SECRET "Paste a new random token, or press Enter to generate one:"
if [[ -z "$MENU_SYNC_TRIGGER_SECRET" ]]; then
  MENU_SYNC_TRIGGER_SECRET=$(openssl rand -base64 48 | tr -d '\n')
  say "Generated a new 48-byte random token."
fi
if [[ ${#MENU_SYNC_TRIGGER_SECRET} -lt 43 || "$MENU_SYNC_TRIGGER_SECRET" =~ [[:space:]] ]]; then
  warn "token must be at least 43 characters with no whitespace"
  exit 1
fi
if ! copySecret "$MENU_SYNC_TRIGGER_SECRET"; then
  warn "no supported clipboard command is available; supply the token yourself on a rerun"
  exit 1
fi

vault_metadata_before=$(readVaultMetadata)
vault_count=$(jq -r '.rows | length' <<<"$vault_metadata_before")
open_url "$SUPABASE_VAULT_URL"
step "Open Vault, then open the Secrets list."
if [[ "$vault_count" == "0" ]]; then
  step "Choose Add new secret."
else
  step "Find ${VAULT_SECRET_NAME} and choose Edit; do not create a duplicate."
fi
step "Use the name ${VAULT_SECRET_NAME}."
step "Paste the clipboard value into Secret. Do not paste it into SQL Editor."
step "Optionally use description: CUpedia production canteen menu sync bearer."
pause "Save the Vault secret, then press Enter to verify metadata."

vault_metadata=$(readVaultMetadata)
vault_transition=$(jq -n \
  --argjson before "$(jq '.rows' <<<"$vault_metadata_before")" \
  --argjson after "$(jq '.rows' <<<"$vault_metadata")" \
  '{before: $before, after: $after}')
if ! printf '%s' "$vault_transition" | \
  node "$ROLLOUT_CONTRACT_SCRIPT" validate-vault-metadata; then
  warn "vault metadata did not change during this rollout"
  jq '{before: (.before | map({id, created_at, updated_at})), after: (.after | map({id, created_at, updated_at}))}' \
    <<<"$vault_transition"
  exit 1
fi
say "Vault metadata shows exactly one named secret; its value was not queried."

stage "Rotate Vercel and GitHub"
say "Vercel is updated and redeployed first. GitHub is switched immediately after the new deployment is Ready."
assertNoMenuSyncRun
assertRotationGap
if ! confirm "Rotate MENU_SYNC_TRIGGER_SECRET in production now?"; then
  warn "credential rotation cancelled; cron remains inactive"
  exit 1
fi
assertNoMenuSyncRun
assertRotationGap

printf '%s' "$MENU_SYNC_TRIGGER_SECRET" | vercel env update \
  MENU_SYNC_TRIGGER_SECRET production \
  --sensitive \
  --yes \
  --cwd "$VERCEL_WORKDIR" \
  --scope "$VERCEL_SCOPE" >/dev/null

deployment_output=$(vercel redeploy \
  "$VERCEL_PRODUCTION_ALIAS" \
  --target production \
  --scope "$VERCEL_SCOPE")
deployment_url=$(printf '%s\n' "$deployment_output" | grep -Eo 'https://[^ ]+\.vercel\.app' | tail -n1)
if [[ -z "$deployment_url" ]]; then
  warn "Vercel redeploy did not return a deployment URL"
  exit 1
fi

deployment_details=$(vercel inspect \
  "$deployment_url" \
  --scope "$VERCEL_SCOPE" \
  --format=json 2>/dev/null)
if ! jq -e '
  .readyState == "READY" and
  .target == "production" and
  (.aliases | index("cupedia.org")) != null
' >/dev/null <<<"$deployment_details"; then
  warn "new Vercel deployment is not Ready on the production alias"
  jq '{url, readyState, target, aliases}' <<<"$deployment_details"
  exit 1
fi

if ! setRepositorySecret MENU_SYNC_TRIGGER_SECRET "$MENU_SYNC_TRIGGER_SECRET"; then
  warn "Vercel has already switched, so scheduled fallback authentication is mismatched; rerun the wizard before the next wake"
  exit 1
fi
clearClipboard || true
say "Vault, Vercel Production, and GitHub Actions now use the same in-memory token."

stage "Post-rotation verification"
say "This stage performs only read-only checks and an unauthenticated 401 probe."

vercel_env_row=$(vercel env ls production \
  --cwd "$VERCEL_WORKDIR" \
  --scope "$VERCEL_SCOPE" 2>&1 | grep 'MENU_SYNC_TRIGGER_SECRET' || true)
if [[ -z "$vercel_env_row" ]]; then
  warn "Vercel no longer lists MENU_SYNC_TRIGGER_SECRET for Production"
  exit 1
fi

github_secret_count=$(gh secret list \
  --repo "$REPOSITORY" \
  --json name \
  --jq '[.[] | select(.name == "MENU_SYNC_TRIGGER_SECRET")] | length')
if [[ "$github_secret_count" != "1" ]]; then
  warn "GitHub does not list exactly one MENU_SYNC_TRIGGER_SECRET"
  exit 1
fi

http_status=$(curl -sS -o /dev/null -w '%{http_code}' \
  -X POST https://cupedia.org/api/internal/canteen-menu-sync/next)
if [[ "$http_status" != "401" ]]; then
  warn "unauthenticated production endpoint returned ${http_status}, expected 401"
  exit 1
fi

scheduler_state=$(readSchedulerState)
if ! jq -e '
  .rows | length == 1 and
  .[0].environment == "unconfigured" and
  (.[0].scheduler_active | not) and
  (.[0].job_active | not) and
  .[0].vault_secret_count == 1 and
  .[0].pending_requests == 0 and
  .[0].worker_check_completed
' >/dev/null <<<"$scheduler_state"; then
  warn "post-rotation scheduler preflight failed"
  jq '.rows' <<<"$scheduler_state"
  exit 1
fi

assertNoReviewRequiredSources

advisor_output=$(supabase db advisors \
  --workdir "$SUPABASE_WORKDIR" \
  --linked \
  --type all \
  --level warn \
  --fail-on none \
  --output-format json)
if ! jq -e '
  (if type == "array" then . else .results end) |
  all(.[];
    (.name == "function_search_path_mutable" and
     .metadata.name == "prevent_campus_bus_arrival_observation_mutation") or
    (.name == "extension_in_public" and .metadata.name == "pg_trgm")
  )
' >/dev/null <<<"$advisor_output"; then
  warn "production advisors contain a new warning"
  jq '(if type == "array" then . else .results end)' <<<"$advisor_output"
  exit 1
fi
say "Credential metadata, inactive scheduler, endpoint guard, and advisors all pass."

stage "Activate Supabase Cron"
warn "This is the production cutover. Issue #757 stays open until #763 is also clean and seven observed days pass."
say "The activation function will re-check the exact job, Vault metadata, UTC timezone, pg_net TTL, and worker."
assertOutsidePrimaryWindow
assertNoMenuSyncRun
assertRotationGap
if ! confirm "Activate cupedia-canteen-menu-sync-wakeup in production?"; then
  warn "activation skipped; all credentials are aligned but cron remains inactive"
  finish
  exit 0
fi
assertOutsidePrimaryWindow
assertNoMenuSyncRun
assertRotationGap
assertNoReviewRequiredSources

activation_result=$(supabaseQuery "SELECT canteen_menu_scheduler.activate() AS result;")
if ! jq -e '.rows | length == 1' >/dev/null <<<"$activation_result"; then
  warn "activation call did not return the expected result"
  exit 1
fi

active_state=$(readSchedulerState)
if ! jq -e '
  .rows | length == 1 and
  .[0].environment == "production" and
  .[0].scheduler_active and
  .[0].job_active and
  .[0].vault_secret_count == 1 and
  .[0].pending_requests == 0
' >/dev/null <<<"$active_state"; then
  warn "activation verification failed; run canteen_menu_scheduler.deactivate() immediately"
  jq '.rows' <<<"$active_state"
  exit 1
fi

say "Supabase Cron is active with the reviewed single-job contract."

stage "Verify the first natural primary window"
say "This read-only stage proves the Cron tick, pg_net delivery, endpoint result, and non-empty business completion agree."
note "If the next window is hours away, exit safely and later run: scripts/issue-764-production-rollout-wizard.sh verify"
pause "Wait until at least 40 minutes after the next 08:17, 11:17, or 17:17 HKT window, then press Enter."
verifyFirstNaturalWindow

finish
